import{_ as n,C as a,o as r,c as i,a3 as l,E as p,w as c,j as s,a as e}from"./chunks/framework.DDJ9jgBL.js";const b=JSON.parse('{"title":"Projects & Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/projects-and-snapshots.md","filePath":"concepts/projects-and-snapshots.md"}'),h={name:"concepts/projects-and-snapshots.md"};function d(g,t,u,f,m,k){const o=a("ManualRelated");return r(),i("div",null,[t[1]||(t[1]=l('<h1 id="projects-snapshots" tabindex="-1">Projects &amp; Snapshots <a class="header-anchor" href="#projects-snapshots" aria-label="Permalink to &quot;Projects &amp; Snapshots&quot;">​</a></h1><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A <strong>project</strong> holds everything about one performance setup:</p><ul><li>32 knobs and all macro mappings</li><li>Up to <strong>8 racks</strong> (MIDI device chains)</li><li>16 LFO configurations and assignments</li><li>Snapshots for scene recall within the project</li><li>Clock source and BPM, default MIDI channel, and encoder-button shortcut</li></ul><p>Use <strong>Main Menu → Project → Library</strong> to create, load, rename, or delete projects. Clock, channel, and encoder live under <strong>Project Settings</strong>. See <a href="./../projects/">Project</a> for save and list workflows.</p><p>Note names (Middle C as C3 or C4), MIDI Thru, contrast, firmware, and bulk migrate stay on <strong>this S32</strong> under <a href="./../settings/">Settings</a>.</p><p><strong>Typical workflow:</strong></p><ol><li>Create or load a project from <strong>Main Menu → Project → Library</strong>.</li><li>Set clock, channel, and encoder under <strong>Project Settings</strong>.</li><li>Build racks, macros, and LFO routing.</li><li><strong>Save Project</strong> when you want changes to survive power-off.</li><li>Use <strong>Save As</strong> on the Library side menu to fork a copy under a new name.</li></ol><p>Switching projects with unsaved edits may prompt you to save or discard. Loading a project applies its clock and channel and <strong>stops</strong> transport.</p><h2 id="snapshot" tabindex="-1">Snapshot <a class="header-anchor" href="#snapshot" aria-label="Permalink to &quot;Snapshot&quot;">​</a></h2><p>A <strong>knob snapshot</strong> captures the <strong>32 pot positions</strong> in the active project for instant recall during a set. Open the slot grid from <a href="./../snapshots/studio">Main Menu → Snapshots</a> after picking Knobs — see <a href="./../snapshots/knob-bank">Knob snapshots</a>. New slots are named <strong>S1</strong>…<strong>S32</strong> from the slot number.</p><p>A <strong>rack snapshot</strong> captures <strong>device parameters</strong> (and the Step Seq pattern) for the highlighted rack. Open it from the rack-list side menu — see <a href="./../snapshots/rack-bank">Rack snapshots</a>.</p><p>An <strong>LFO snapshot</strong> captures <strong>all 16 S32 LFO configs</strong> (and CV16 configs when present). It does not store assignment wiring. Open it from the LFO-grid Options menu — see <a href="./../snapshots/lfo-bank">LFO snapshots</a>.</p><p><strong>Arrange</strong> is a 16-row song grid of already stored snapshots across Knobs, LFOs, and racks. When the playhead lands on a row it recalls occupied cells as a scene; rest (<code>--</code>) skips that bank. Open <strong>ARRANGE</strong> from <a href="./../navigation/main-menu">Main Menu</a> (first item) — see <a href="./../snapshots/lanes">Arrange</a>.</p><p><strong>Morph</strong> glides from the live sound to an occupied pad (<strong>this bank&#39;s FADE TIME</strong>; Arrange playhead uses <strong>Arrange FADE TIME</strong>). Another occupied pad retargets. See <a href="./../snapshots/morph">Morph</a>.</p><p><strong>Use snapshots when:</strong></p><ul><li>You need fast scene changes (intro / drop / outro) within one project.</li><li>You want to experiment, then jump back to a known point.</li></ul><p><strong>Use Save Project when:</strong></p><ul><li>You changed structure (new devices, macro modes, LFO wiring) or Project Settings and want it after power off.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Live take and recall live on Main Menu → Snapshots (the BANK pad) and on the rack / LFO side menus.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>Build and <strong>Save Project</strong> once per song or set.</li><li>Use <strong>snapshots</strong> for sections within that set.</li><li><strong>Save As</strong> on the Library to fork a variation under another name.</li></ol></div>',21)),p(o,null,{default:c(()=>[...t[0]||(t[0]=[s("ul",null,[s("li",null,[s("a",{href:"./../projects/"},"Project"),e(" — Create, load, rename, and save projects")]),s("li",null,[s("a",{href:"./../snapshots/"},"Snapshots"),e(" — Snapshot overview")]),s("li",null,[s("a",{href:"./../snapshots/knob-bank"},"Knob snapshots"),e(" — Take and recall from BANK")]),s("li",null,[s("a",{href:"./../snapshots/rack-bank"},"Rack snapshots"),e(" — Take and recall from the rack side menu")]),s("li",null,[s("a",{href:"./../snapshots/lfo-bank"},"LFO snapshots"),e(" — Take and recall from the LFO grid")]),s("li",null,[s("a",{href:"./../snapshots/morph"},"Morph"),e(" — Live to a pad with this bank's FADE TIME")]),s("li",null,[s("a",{href:"./../snapshots/lanes"},"Arrange"),e(" — Clocked 16-row song grid")]),s("li",null,[s("a",{href:"./rack-chains"},"Rack chains"),e(" — Racks and device chains in a project")])],-1)])]),_:1})])}const S=n(h,[["render",d]]);export{b as __pageData,S as default};
